/**
 * LLM-generated analyst commentary for a real, detected central-bank rate
 * decision — short/medium/long-term impact plus a probable-trajectory view.
 *
 * This is this app's second deliberate LLM-computed, user-facing surface
 * (the first is /dashboard/prediction — see openaiAnalysis.ts's own doc
 * comment on why that carve-out exists). It exists because "probable future
 * rate trajectory" is inherently a judgment call, not a deterministic
 * function of stored data the way this app's z-scores/ADF tests/event
 * studies are — so it is generated by an LLM instead of computed, and always
 * disclosed as such on the page, never presented as a verified metric.
 *
 * Every fact handed to the model is real, live data already stored in
 * metric_series (the detected rate move, a recent FX change, and this app's
 * own real historical event-study numbers) — the model is explicitly
 * instructed not to invent additional facts, only to reason qualitatively
 * about what's given.
 */

const OPENAI_API_KEY = process.env.OPENAI_API_KEY;
const MODEL = process.env.OPENAI_PREDICTION_MODEL || "gpt-4.1-mini";

export type CommentaryInput = {
  institution: string;
  countryLabel: string;
  rateLabel: string;
  fromLevel: number;
  toLevel: number;
  changeBps: number;
  eventDate: string;
  fxLabel: string | null;
  fxLatest: number | null;
  fxChangePct: number | null;
  equityLabel: string;
  equityImpact: { horizonLabel: string; avgChangePct: number | null; sampleSize: number }[];
  pastHikeCount: number;
  pastCutCount: number;
};

export type DecisionCommentary = {
  shortTerm: string;
  mediumTerm: string;
  longTerm: string;
  trajectory: string;
};

function buildPrompt(input: CommentaryInput): string {
  const direction = input.changeBps >= 0 ? "hike" : "cut";
  const fxLine =
    input.fxLabel && input.fxLatest !== null
      ? `- ${input.fxLabel} latest: ${input.fxLatest}${
          input.fxChangePct !== null ? ` (${input.fxChangePct >= 0 ? "+" : ""}${input.fxChangePct.toFixed(2)}% over the past ~2 weeks)` : ""
        }`
      : "- No live FX cross tracked for this bank in this app";

  const eventStudyLine = input.equityImpact
    .map((h) => `${h.horizonLabel}: ${h.avgChangePct !== null ? `${h.avgChangePct >= 0 ? "+" : ""}${h.avgChangePct}% avg (n=${h.sampleSize})` : `no data (n=${h.sampleSize})`}`)
    .join("; ");

  return `You are writing internal analyst commentary for a financial systemic-risk dashboard about a real, just-detected central bank interest-rate ${direction}. Output ONLY a single valid JSON object, no markdown fences, no prose outside the JSON, with exactly these four string keys: "shortTerm", "mediumTerm", "longTerm", "trajectory".

REAL DATA — this is everything you may treat as fact. Do not invent additional numbers, dates, vote counts, or news events beyond what is given here:
- Institution: ${input.institution} (${input.countryLabel})
- Policy rate series tracked: ${input.rateLabel}
- Detected move: ${input.fromLevel}% -> ${input.toLevel}% (${input.changeBps >= 0 ? "+" : ""}${input.changeBps}bp), detected around ${input.eventDate}
${fxLine}
- Bank-equity proxy tracked: ${input.equityLabel}
- Real historical event-study (this app's own computed average % change in that equity proxy after this bank's past hikes): ${eventStudyLine}
- This bank's detected history: ${input.pastHikeCount} hike(s) and ${input.pastCutCount} cut(s) on record in this app's stored data

Write, in plain prose (2-4 sentences each, concrete and specific to this bank/country, no generic filler):
- "shortTerm": likely effects over the next 1-4 weeks, grounded in the data above.
- "mediumTerm": likely effects over the next 1-2 quarters (funding costs, currency, bank margins, capital flows — whichever actually apply to this country).
- "longTerm": the broader multi-quarter/structural picture for this bank/economy.
- "trajectory": your qualitative best-guess view of the likely DIRECTION and pacing of this bank's next moves, explicitly hedged as a probabilistic judgment (e.g. "likely gradual further tightening conditional on inflation data" or "likely on hold pending X"). Never state a specific future date or exact future rate level as if it were a known fact.

If the event-study sample size for a horizon is small (n<3), say the historical read is low-confidence rather than treating it as reliable. Do not fabricate specific news, quotes, or dissent counts beyond what's given.`;
}

type MessageContent = { type: string; text?: string };
type OutputItem = { type: string; content?: MessageContent[] };
type ResponsesBody = { output?: OutputItem[]; error?: { message?: string } };

// This now runs inline in a user-facing page render (see
// centralBankDecisionCommentary.ts's cache) rather than only from a
// user-triggered button click like /dashboard/prediction — so unlike
// openaiAnalysis.ts, a slow/hung OpenAI response must not be allowed to hang
// the whole page. Bounded well under the Banking page's own maxDuration.
const REQUEST_TIMEOUT_MS = 15_000;

export async function generateCentralBankCommentary(input: CommentaryInput): Promise<DecisionCommentary | null> {
  if (!OPENAI_API_KEY) return null;
  try {
    const res = await fetch("https://api.openai.com/v1/responses", {
      method: "POST",
      headers: { Authorization: `Bearer ${OPENAI_API_KEY}`, "Content-Type": "application/json" },
      body: JSON.stringify({ model: MODEL, input: buildPrompt(input) }),
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });
    const body = (await res.json().catch(() => null)) as ResponsesBody | null;
    if (!res.ok || !body) {
      console.error(`generateCentralBankCommentary(${input.institution}): HTTP ${res.status} ${body?.error?.message ?? ""}`);
      return null;
    }

    const text = (body.output ?? [])
      .filter((o) => o.type === "message")
      .flatMap((o) => o.content ?? [])
      .filter((c) => c.type === "output_text" && c.text)
      .map((c) => c.text as string)
      .join("\n")
      .trim();

    const match = text.match(/\{[\s\S]*\}/);
    if (!match) return null;
    const parsed: unknown = JSON.parse(match[0]);
    if (
      typeof parsed !== "object" ||
      parsed === null ||
      typeof (parsed as Record<string, unknown>).shortTerm !== "string" ||
      typeof (parsed as Record<string, unknown>).mediumTerm !== "string" ||
      typeof (parsed as Record<string, unknown>).longTerm !== "string" ||
      typeof (parsed as Record<string, unknown>).trajectory !== "string"
    ) {
      return null;
    }
    const p = parsed as Record<string, string>;
    return { shortTerm: p.shortTerm, mediumTerm: p.mediumTerm, longTerm: p.longTerm, trajectory: p.trajectory };
  } catch (e) {
    console.error(`generateCentralBankCommentary(${input.institution}):`, (e as Error).message);
    return null;
  }
}
